async function scanning(){
 const m='scanning_dwm'; if(!can(m,'view')) return $('main').innerHTML='<div class="alert alert-error">No access to 3D Scanning DWM & OEE.</div>';
 const today=new Date().toISOString().slice(0,10);
 let er=await sb.from('scanning_engineers').select('*').eq('active',true).order('engineer_name');
 let tr=await sb.from('scanning_tasks').select('*,scanning_engineers(engineer_name,employee_id)').eq('task_date',today).order('id',{ascending:false});
 let engineers=er.data||[], tasks=tr.data||[];
 if(tr.error) return $('main').innerHTML=`<div class="alert alert-error">${esc(tr.error.message)}</div>`;
 const done=tasks.filter(x=>String(x.work_status).toLowerCase()==='completed').length;
 const ok=tasks.filter(x=>String(x.work_status).toLowerCase()==='completed' && ['OK','APPROVED'].includes(String(x.final_result||'').toUpperCase())).length;
 const planned=tasks.reduce((a,x)=>a+(+x.planned_minutes||0),0), actual=tasks.reduce((a,x)=>a+(+x.actual_minutes||0),0), down=tasks.reduce((a,x)=>a+(+x.downtime_minutes||0),0);
 const av=planned?Math.max(0,Math.min(1,(planned-down)/planned))*100:0, pe=actual?Math.max(0,Math.min(1,planned/actual))*100:0, qu=done?ok/done*100:0, oee=av*pe*qu/10000;
 $('main').innerHTML=`<div class="page-title"><div><h1>3D Scanning DWM & OEE</h1><p>Two-shift daily work management • Engineer-wise task assignment • OEE-style KPI</p></div>${admin()?`<button class="btn btn-secondary" onclick="manageScanEngineers()">Manage Engineers</button>`:''}${can(m,'add')?`<button class="btn btn-primary" onclick="scanForm()">+ Assign Scanning Task</button>`:''}</div>
 <div class="stats stylish-stats"><div class="stat"><div class="icon">📋</div><div class="n">${tasks.length}</div><div class="l">Today's Tasks</div></div><div class="stat"><div class="icon">⏱️</div><div class="n">${av.toFixed(1)}%</div><div class="l">Availability</div></div><div class="stat"><div class="icon">⚡</div><div class="n">${pe.toFixed(1)}%</div><div class="l">Performance</div></div><div class="stat"><div class="icon">🎯</div><div class="n">${oee.toFixed(1)}%</div><div class="l">OEE</div></div></div>
 <div class="panel"><div class="searchbar advanced-searchbar"><input id="scan_q" placeholder="Quick search engineer, customer, part, task..." oninput="filterScan()"><button class="btn btn-secondary" onclick="openScanAdvancedFilter()">⚙ Advanced Filter</button><button class="btn btn-secondary" onclick="clearScanAdvancedFilter()">Clear Filters</button></div><div id="scan_filter_summary" class="filter-summary"></div><div class="tablewrap"><table><thead><tr><th>Date</th><th>Shift</th><th>Plant</th><th>Engineer</th><th>Customer</th><th>Part</th><th>Work Type</th><th>Priority</th><th>Planned</th><th>Status</th><th>Result</th><th>Action</th></tr></thead><tbody id="scan_rows">${scanRows(tasks)}</tbody></table></div></div>`;
 window._scanTasks=tasks; window._scanEngineers=engineers;
}
function scanRows(tasks){return (tasks||[]).map(x=>`<tr><td>${esc(x.task_date)}</td><td><span class="badge ${x.shift_code==='A'?'active':'review'}">${esc(x.shift_code)}</span></td><td>${esc(x.plant_unit)}</td><td>${esc(x.scanning_engineers?.engineer_name||'Unassigned')}</td><td>${esc(x.customer_name)}</td><td>${esc(x.part_short_name)}</td><td>${esc(x.work_type)}</td><td>${esc(x.priority)}</td><td>${esc(x.planned_minutes)} min</td><td>${esc(x.work_status)}</td><td>${esc(x.final_result)}</td><td>${can('scanning_dwm','edit')?`<button class="btn btn-secondary" onclick="editScan(${x.id})">Edit</button>`:`<button class="btn btn-secondary" onclick="viewScan(${x.id})">View</button>`}${admin()?` <button class="btn btn-danger" onclick="deleteScan(${x.id})">Delete</button>`:''}</td></tr>`).join('')||'<tr><td colspan="12" class="empty">No tasks found.</td></tr>'}
const SCAN_FILTERS=[['task_date','Date'],['shift_code','Shift'],['plant_unit','Plant / Unit'],['customer_name','Customer'],['part_short_name','Part / Short Name'],['part_no','Part No.'],['priority','Priority'],['work_type','Work Type'],['work_status','Status'],['final_result','Final Result'],['report_no','Report No.']];
function openScanAdvancedFilter(){const st=window._scanAdvFilters||{};$('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal filter-modal"><div class="modal-header"><div><h2>3D Scanning Advanced Filter</h2><p class="small">Combine date, shift, plant, customer, engineer and task conditions.</p></div><button class="close" onclick="closeM()">×</button></div><div class="filter-grid">${SCAN_FILTERS.map(f=>filterInput(f,st[f[0]]||'')).join('')}<div class="form-group"><label>Scanning Engineer</label><input id="af_scan_engineer" value="${esc(st._engineer||'')}" placeholder="Engineer name"></div></div><div class="actions"><button class="btn btn-secondary" onclick="clearScanAdvancedFilter(true)">Clear</button><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary" onclick="applyScanAdvancedFilter()">Apply Filter</button></div></div></div>`)}
function collectScanFilters(){const o={};SCAN_FILTERS.forEach(f=>{const k=f[0];if(k==='task_date'){const from=$('af_task_date_from')?.value||'',to=$('af_task_date_to')?.value||'';if(from||to)o[k]={from,to}}else{const v=$('af_'+k)?.value?.trim()||'';if(v)o[k]=v}});const eng=$('af_scan_engineer')?.value?.trim()||'';if(eng)o._engineer=eng;return o}
function applyScanAdvancedFilter(){window._scanAdvFilters=collectScanFilters();closeM();filterScan()}
function clearScanAdvancedFilter(inside=false){window._scanAdvFilters={};if(inside)closeM();filterScan()}
function scanAdvMatch(x){const st=window._scanAdvFilters||{};return Object.entries(st).every(([k,v])=>{if(k==='_engineer')return String(x.scanning_engineers?.engineer_name||'').toLowerCase().includes(v.toLowerCase());if(typeof v==='object'){const d=x[k]?String(x[k]).slice(0,10):'';return (!v.from||d>=v.from)&&(!v.to||d<=v.to)}return String(x[k]??'').toLowerCase().includes(String(v).toLowerCase())})}
function filterScan(){let q=($('scan_q')?.value||'').toLowerCase(),a=(window._scanTasks||[]).filter(x=>scanAdvMatch(x)&&(!q||JSON.stringify(x).toLowerCase().includes(q)));$('scan_rows').innerHTML=scanRows(a);if($('scan_filter_summary'))$('scan_filter_summary').innerHTML=`<span class="small">${Object.keys(window._scanAdvFilters||{}).length?'<b>Advanced filters active.</b> ':''}${a.length} result${a.length===1?'':'s'}</span>`}
async function scanForm(id){
 if(!can('scanning_dwm',id?'edit':'add'))return alert('No permission.');
 let x={task_date:new Date().toISOString().slice(0,10),shift_code:'A',plant_unit:'MFPL',priority:'Medium',work_status:'Assigned',planned_minutes:60};
 if(id){let r=await sb.from('scanning_tasks').select('*').eq('id',id).single();if(r.error)return alert(r.error.message);x=r.data}
 let er=await sb.from('scanning_engineers').select('*').eq('active',true).order('engineer_name');let engineers=er.data||[];
 $('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal"><div class="modal-header"><h2>${id?'Edit':'Assign'} Scanning Task</h2><button class="close" onclick="closeM()">×</button></div><div id="sfm"></div><form onsubmit="saveScan(event,${id||0})"><div class="grid3">
 <div class="form-group"><label>Task Date</label><input id="s_task_date" type="date" value="${esc(x.task_date)}" required></div><div class="form-group"><label>Shift</label><select id="s_shift"><option ${x.shift_code==='A'?'selected':''}>A</option><option ${x.shift_code==='B'?'selected':''}>B</option></select></div><div class="form-group"><label>Plant / Unit</label><input id="s_plant" value="${esc(x.plant_unit||'')}" required></div>
 <div class="form-group"><label>Assigned Scanning Engineer</label><select id="s_eng"><option value="">Unassigned</option>${engineers.map(e=>`<option value="${e.id}" ${String(x.assigned_engineer_id)===String(e.id)?'selected':''}>${esc(e.engineer_name)} (${esc(e.employee_id||'')})</option>`).join('')}</select></div>
 ${[['customer_name','Customer'],['part_short_name','Part / Short Name'],['part_no','Part No.'],['material_type','Material Type'],['cavity_note','Cavity / Qty Note'],['received_qty','Received Qty'],['unit','Unit'],['priority','Priority'],['work_type','Work Type'],['planned_minutes','Planned Minutes'],['work_details','Work Details'],['reason','Reason']].map(f=>`<div class="form-group"><label>${f[0]==='priority'?'Priority':f[1]}</label>${f[0]==='priority'?`<select id="s_${f[0]}">${['Low','Medium','High'].map(v=>`<option ${x[f[0]]===v?'selected':''}>${v}</option>`).join('')}</select>`:`<input id="s_${f[0]}" value="${esc(x[f[0]]||'')}">`}</div>`).join('')}
 <div class="form-group"><label>Status</label><select id="s_work_status">${['Assigned','In Progress','On Hold','Completed','Cancelled'].map(v=>`<option ${x.work_status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-group"><label>Final Result</label><select id="s_final_result"><option value="">-</option>${['OK','NG','Approved','Rejected'].map(v=>`<option ${x.final_result===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-group"><label>Report No.</label><input id="s_report_no" value="${esc(x.report_no||'')}"></div>
 <div class="form-group full"><label>Observation / Abnormality</label><textarea id="s_observation">${esc(x.observation||'')}</textarea></div><div class="form-group full"><label>Remarks</label><textarea id="s_remark">${esc(x.remark||'')}</textarea></div>
 </div><div class="actions"><button type="button" class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary">Save Task</button></div></form></div></div>`)
}
async function saveScan(e,id){e.preventDefault();let o={task_date:$('s_task_date').value,shift_code:$('s_shift').value,plant_unit:$('s_plant').value,assigned_engineer_id:$('s_eng').value||null,customer_name:$('s_customer_name').value,part_short_name:$('s_part_short_name').value,part_no:$('s_part_no').value,material_type:$('s_material_type').value,cavity_note:$('s_cavity_note').value,received_qty:+$('s_received_qty').value||null,unit:$('s_unit').value,priority:$('s_priority').value,work_type:$('s_work_type').value,planned_minutes:+$('s_planned_minutes').value||0,work_details:$('s_work_details').value,reason:$('s_reason').value,work_status:$('s_work_status').value,final_result:$('s_final_result').value,report_no:$('s_report_no').value,observation:$('s_observation').value,remark:$('s_remark').value,updated_by:currentUser.id};let r=id?await sb.from('scanning_tasks').update(o).eq('id',id).select().single():await sb.from('scanning_tasks').insert({...o,created_by:currentUser.id,assigned_by:currentUser.id}).select().single();if(r.error)return err('sfm',r.error.message);closeM();scanning()}
async function deleteScan(id){if(!admin())return alert('Only Admin can delete scanning tasks.');if(!confirm('Delete this scanning task? This action cannot be undone.'))return;const r=await sb.from('scanning_tasks').delete().eq('id',id);if(r.error)return alert(r.error.message);scanning()}
function editScan(id){scanForm(id)}
function viewScan(id){let x=(window._scanTasks||[]).find(v=>v.id===id);if(!x)return;alert(`Task ${x.task_no||x.id}\nEngineer: ${x.scanning_engineers?.engineer_name||'Unassigned'}\nStatus: ${x.work_status}\nResult: ${x.final_result||'-'}`)}

async function manageScanEngineers(){
 if(!admin())return;
 let u=await sb.from('user_profiles').select('id,employee_id,employee_name,department,designation,plant_unit').eq('approval_status','Approved').order('employee_name');
 if(u.error)return alert(u.error.message);
 let e=await sb.from('scanning_engineers').select('*'); if(e.error)return alert(e.error.message);
 const existing=Object.fromEntries((e.data||[]).map(x=>[x.user_id,x]));
 window._scanEngineerIds=(u.data||[]).map(x=>x.id); $('app').insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modal"><div class="modal"><div class="modal-header"><h2>Scanning Engineer Master</h2><button class="close" onclick="closeM()">×</button></div><div class="tablewrap"><table><thead><tr><th>Use</th><th>Engineer</th><th>Employee ID</th><th>Plant</th><th>Default Shift</th></tr></thead><tbody>${(u.data||[]).map(x=>{let z=existing[x.id]||{};return `<tr><td><input type="checkbox" id="se_use_${x.id}" ${z.active?'checked':''}></td><td>${esc(x.employee_name)}<br><small>${esc(x.designation||'')}</small></td><td>${esc(x.employee_id||'')}</td><td><input id="se_plant_${x.id}" value="${esc(z.plant_unit||x.plant_unit||'')}"></td><td><select id="se_shift_${x.id}"><option ${z.default_shift==='A'?'selected':''}>A</option><option ${z.default_shift==='B'?'selected':''}>B</option></select></td></tr>`}).join('')}</tbody></table></div><div class="actions"><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary" onclick="saveScanEngineers()">Save Engineers</button></div></div></div>`)
}
async function saveScanEngineers(){
 for(const id of (window._scanEngineerIds||[])){const use=$(`se_use_${id}`)?.checked;const user=(await sb.from('user_profiles').select('employee_id,employee_name,plant_unit').eq('id',id).single()).data||{};let r=await sb.from('scanning_engineers').upsert({user_id:id,employee_id:user.employee_id,engineer_name:user.employee_name,plant_unit:$(`se_plant_${id}`).value,default_shift:$(`se_shift_${id}`).value,active:use},{onConflict:'user_id'});if(r.error)return alert(r.error.message)}
 alert('Scanning engineer master saved.');closeM();scanning();
}
